import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Coding Style","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-dev-guide/contribute/coding_style.md","filePath":"en/qgc-dev-guide/contribute/coding_style.md"}`),a={name:`en/qgc-dev-guide/contribute/coding_style.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="coding-style" tabindex="-1">Coding Style <a class="header-anchor" href="#coding-style" aria-label="Permalink to “Coding Style”">​</a></h1><p>The canonical style guide is <a href="https://github.com/mavlink/qgroundcontrol/blob/master/CODING_STYLE.md" target="_blank" rel="noreferrer">CODING_STYLE.md</a> in the source tree. High level style information:</p><ul><li>Indent with 4 spaces (no tabs); lines are at most 120 columns.</li><li><code>PascalCase</code> class names, <code>camelCase</code> methods and variables, <code>_leadingUnderscore</code> private members.</li><li>C++20 and Qt 6 idioms: always null-check <code>Vehicle*</code>/<code>activeVehicle()</code>, use categorized logging (<code>qCDebug</code>/<code>qCWarning</code>), and no <code>Q_ASSERT</code> in production code.</li><li>QML uses QGC controls, <code>ScreenTools</code> sizes and <code>QGCPalette</code> colors instead of hardcoded values, and wraps user-visible strings in <code>qsTr()</code>.</li></ul><p>The style itself is demonstrated in the following example files:</p><ul><li><a href="https://github.com/mavlink/qgroundcontrol/blob/master/tools/coding-style/CodingStyle.cc" target="_blank" rel="noreferrer">CodingStyle.cc</a></li><li><a href="https://github.com/mavlink/qgroundcontrol/blob/master/tools/coding-style/CodingStyle.h" target="_blank" rel="noreferrer">CodingStyle.h</a></li><li><a href="https://github.com/mavlink/qgroundcontrol/blob/master/tools/coding-style/CodingStyle.qml" target="_blank" rel="noreferrer">CodingStyle.qml</a></li></ul><p>Formatting and linting are enforced by pre-commit hooks (clang-format, qmllint, and QGC-specific checks); run <code>just lint</code> before you push. Only format the lines you change: whole-file reformatting of existing files creates unrelated diffs that make pull requests harder to review.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};